  blockquote, q {
    quotes: none;
  }
  blockquote::before, blockquote::after, q::before, q::after {
    content: none;
  }
  table {
    border-collapse: collapse;
    border-spacing: 0;
  }
  a, button {
    cursor: pointer;
  }
  button {
    padding: 0;
    font-family: inherit;
  }
  hidden {
    display: none;
  }
  :disabled {
    cursor: not-allowed;
  }
